// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        bool success;
        try c.setOwner(newOwner) returns (bool result) {
            success = result;
        } catch {
            success = false;
        }
        if (success) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}

