pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address originalOwner = c.owner();
        vm.assume(newOwner != originalOwner);
        bool refSuccess = false;
        try c.setOwner(newOwner) { refSuccess = true; } catch {}
        assertTrue(refSuccess == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(true);
        }
    }
}
